{
  "name": "AMI超导磁体持久电流开关系统",
  "name_en": "AMI superconducting magnet with persistent current switch",
  "manufacturer": "American Magnetics, Inc. (AMI)",
  "description": "这是一套用于低温实验的超导磁体系统，配有持久电流开关和外部电流源控制。它可将目标磁场换算为励磁电流，对磁体进行升降场，并在持久模式下维持稳定磁场，常用于量子器件、纳米器件和低温输运测量中的磁场施加与保持。",
  "description_en": "This is a superconducting magnet system for cryogenic experiments, equipped with a persistent current switch and controlled by an external current source. It converts target magnetic field values into drive currents, ramps the magnet field, and maintains a stable field in persistent mode. It is commonly used for applying and holding magnetic fields in quantum-device, nanodevice, and low-temperature transport measurements.",
  "tag_hints": [
    "superconducting magnet",
    "persistent current switch",
    "magnetic field control",
    "cryogenic experiments",
    "magnet power supply",
    "field-to-current conversion"
  ],
  "actions": [
    {
      "action_name": "auto-get_all",
      "description": "读取磁体系统的全部主要状态信息。",
      "description_en": "Read all main status information of the magnet system."
    },
    {
      "action_name": "auto-get_source_current",
      "description": "读取电流源输出电流。",
      "description_en": "Get the source output current."
    },
    {
      "action_name": "auto-set_source_current",
      "description": "设置电流源输出电流。",
      "description_en": "Set the source output current."
    },
    {
      "action_name": "auto-get_heater_current",
      "description": "读取持久电流开关加热器电流。",
      "description_en": "Get the persistent switch heater current."
    },
    {
      "action_name": "auto-get_switch_state",
      "description": "读取持久电流开关状态。",
      "description_en": "Get the persistent current switch state."
    },
    {
      "action_name": "auto-set_switch_state",
      "description": "设置持久电流开关状态。",
      "description_en": "Set the persistent current switch state."
    },
    {
      "action_name": "auto-set_field",
      "description": "设置目标磁场。",
      "description_en": "Set the target magnetic field."
    },
    {
      "action_name": "auto-get_field",
      "description": "读取当前持久磁场。",
      "description_en": "Get the current persistent magnetic field."
    },
    {
      "action_name": "auto-step_magfield_to_value",
      "description": "将磁场逐步调节到指定值。",
      "description_en": "Step the magnetic field to a specified value."
    },
    {
      "action_name": "auto-disconnect_source",
      "description": "断开电流源与磁体回路的连接。",
      "description_en": "Disconnect the current source from the magnet circuit."
    },
    {
      "action_name": "auto-bring_source_to_field",
      "description": "将电流源调整到与当前磁场对应的电流值。",
      "description_en": "Bring the source to the current corresponding to the present magnetic field."
    },
    {
      "action_name": "auto-measure_field",
      "description": "测量或读取磁场值。",
      "description_en": "Measure or read the magnetic field value."
    },
    {
      "action_name": "auto-BtoI",
      "description": "将磁场值换算为对应电流。",
      "description_en": "Convert a magnetic field value to the corresponding current."
    },
    {
      "action_name": "auto-ItoB",
      "description": "将电流值换算为对应磁场。",
      "description_en": "Convert a current value to the corresponding magnetic field."
    },
    {
      "action_name": "auto-fake_folder",
      "description": "创建用于记录磁场或开关状态变化的占位实验文件夹。",
      "description_en": "Create a placeholder experiment folder used to record a magnetic-field or switch-state change."
    }
  ]
}

